      conteudo: `12.1. Conceito e características
Contrato administrativo é “o ajuste que a Administração Pública, agindo nessa qualidade,
firma com particular ou outra entidade administrativa para a consecução de objetivos de interesse
público, nas condições estabelecidas pela própria Administração” (Hely Lopes Meirelles. 2016, p.
239).
Observe que nem todo contrato celebrado pela administração pública será um “contrato ad-
ministrativo”, regido pelo direito público e com a incidência das prerrogativas e limitações de Estado.
Com efeito, em determinadas situações a administração pública irá celebrar contratos regidos pelo
direito privado, como nos contratos das empresas estatais, regidas pela Lei 13.303/16.
Como visto no capítulo anterior, a Lei 14.133/21 é a Lei geral de Licitações e Contratos
Administrativos no Brasil. Aplica-se a Lei 14.133/21, no que couber e na ausência de norma
específica, aos convênios, acordos, ajustes e outros instrumentos congêneres celebrados por
órgãos e entidades da Administração Pública;
Cuidado! Há vários contratos e instrumentos congêneres na legislação esparsa:
• Lei 8.987/95 (Concessão comum);
• Lei 11.079/04 (Concessão especial – PPP);
Direito Administrativo
• Lei 11.107/05 (Consórcios Públicos);
• Lei 13019/14 (OSC – Termo de colaboração, Termo de Fomento, Acordo de coopera-
ção);
• Convênios: são ajustes entre entidades ou órgãos da administração pública. Diferente
dos contratos, as partes convenentes possuem vontades convergentes, não sendo
necessária a realização de licitação antes de firmar o ajuste.
Embora regidos pelo direito público, na ausência de disposição expressa, aos contratos ad-
ministrativos poderão ser aplicados, supletivamente, os princípios da teoria geral dos contratos e as
disposições de direito privado, conforme art. 89 da Lei 14.133/21.
Atenção! Os Contratos nas Estatais (Empresas Públicas e Sociedades de Economia Mista),
conforme Lei 13.303/16, são regidos diretamente (e não supletivamente) pelas disposições de direito
privado. Portanto, eles não têm as características dos “contratos administrativos”, embora sejam
contratos “da” administração pública.
A principal característica dos contratos administrativos é a verticalidade, decorrente da su-
premacia do interesse público, e que concede à administração prerrogativas em face dos particu-
lares contratados. Tais prerrogativas se manifestam nas chamadas cláusulas exorbitantes, previs-
tas no art. 104, da lei 14.133/21, estando presentes, implicitamente, em todos os contratos adminis-
trativos.
12.2. Formalização dos contratos administrativos
Após a licitação ou processo de contratação direta, a Administração convoca licitante vence-
dor para assinar o termo de contrato ou equivalente, dentro do prazo e nas condições estabelecidas
no edital de licitação, sob pena de decair o direito à contratação.
Se nenhum licitante aceitar a contratação nos termos da proposta vencedora, a Admi-
nistração pode:
1) convocar os licitantes remanescentes para negociação, na ordem de classificação,
com vistas à obtenção de preço melhor, mesmo que acima do preço do adjudicatário;
2) adjudicar e celebrar o contrato nas condições ofertadas pelos licitantes remanescen-
tes, atendida a ordem classificatória, quando frustrada a negociação de melhor condi-
ção.
Direito Administrativo
Observação: recusa injustificada do adjudicatário (vencedor da licitação) caracteriza des-
cumprimento total da obrigação assumida e sujeita às penalidades e imediata perda da garantia de
proposta.
O art. 92 da Lei 14.133/21 prevê uma lista de cláusulas necessárias nos contratos.
O contrato administrativo será sempre escrito e obrigatório, salvo nas seguintes hipóteses:
• dispensa de licitação em razão de valor;
• compras com entrega imediata e integral dos bens adquiridos e dos quais não resul-
tem obrigações futuras, inclusive quanto a assistência técnica, independentemente de
seu valor.
Nesses casos o contrato administrativo pode ser substituído por um “equivalente”: carta-con-
trato, nota de empenho de despesa, autorização de compra ou ordem de execução de serviço.
Atenção! É considerado nulo e de nenhum efeito o contrato verbal com a Administração,
salvo o de pequenas compras ou o de prestação de serviços de pronto pagamento.
Em atenção ao Princípio da Publicidade, a divulgação no Portal Nacional de Contratações
Públicas (PNCP) é condição indispensável para a eficácia do contrato e de seus aditamentos.
12.3. Garantia
Pode ser exigida (no edital) prestação de garantia nas contratações de obras, serviços e
fornecimentos. Caberá ao contratado optar por uma das seguintes modalidades de garantia:
O valor máximo a ser exigido de garantia é de 5% do valor do contrato, podendo ser majorado,
justificadamente, até 10% do valor inicial do contrato. Em obras e serviços de engenharia de grande
vulto: seguro-garantia de até 30%.
Trata-se de garantia para execução do contrato. Não confunda com garantia da proposta (que
pode ser exigida na licitação). A garantia prestada pelo contratado será liberada ou restituída após
a fiel execução do contrato ou após a sua extinção por culpa exclusiva da Administração e,
quando em dinheiro, atualizada monetariamente.
Direito Administrativo
Na contratação de obras e serviços de engenharia, o edital poderá exigir a prestação da
garantia na modalidade seguro-garantia e prever a obrigação de a seguradora, em caso de inadim-
plemento pelo contratado, assumir a execução e concluir o objeto do contrato (cláusula step-in).
12.4. Alocação de riscos
Considerando os riscos contratuais previstos e presumíveis, poderá o edital prever matriz de
alocação de riscos, alocando-os entre contratante e contratado, mediante indicação daqueles a
serem assumidos pelo setor público ou pelo setor privado, ou daqueles a serem compartilhados.
Conforme art. 103 da lei 14.133/21, a matriz de alocação de riscos definirá o equilíbrio eco-
nômico-financeiro inicial do contrato em relação a eventos supervenientes e deverá ser observada
na solução de eventuais conflitos. Sempre que atendidas as condições do contrato e da matriz de
alocação de riscos, será considerado mantido o equilíbrio econômico-financeiro, renunciando as par-
tes aos pedidos de restabelecimento do equilíbrio relacionados aos riscos assumidos, exceto no que
se refere:
• Alterações unilaterais pela Administração (previstas no art. 124, I);
• Aumento ou à redução, por legislação superveniente, dos tributos diretamente pagos
pelo contratado em decorrência do contrato.
Atenção! Será obrigatória a matriz de alocação de riscos nos casos de contratação de
obras e serviços de grande vulto ou quando adotados os regimes de contratação integrada e
semi-integrada.
12.5. Prerrogativas da administração – cláusulas exorbitantes
O regime dos contratos administrativos, fundado no princípio da supremacia do interesse pú-
blico sobre o privado, garante uma série de vantagens (prerrogativas) à Administração Pública, que
não decorrem do acordo entre as partes. Essas vantagens não precisam estar escritas, expressa-
mente, no contrato (são implícitas). Por isso são chamadas de “cláusulas exorbitantes”, pois sua
previsão decorre da lei (ex lege), e não da vontade das partes.
O exemplo mais cobrado é a possibilidade de alteração unilateral dos contratos, por vontade
da administração, desde que respeitados os limites e condições legais. Essa é a característica da
“instabilidade” ou “mutabilidade” dos contratos administrativos. Como exemplos, temos a exigência
de garantia ao contratado, bem como a restrição à oposição de exceção do contrato não cumprido
(art. 137, IV).
Direito Administrativo
No art. 104, da Lei 14.133/21 encontramos o rol dessas prerrogativas.
Há limites para essas vantagens. Por exemplo: as cláusulas econômico-financeiras e mone-
tárias dos contratos não poderão ser alteradas sem prévia concordância do contratado.
Atenção! Essas cláusulas exorbitantes não estão presentes na Lei 13.303/16, que rege
os contratos das estatais. Portando, as empresas públicas e sociedades de economia mista, no
geral, estão em maior “igualdade” com os contratados, pois não possuem as prerrogativas que
outras entidades da administração pública gozam em relação aos seus contratos, regidos pela
lei geral.
12.6. Prazos – duração dos contratos
O prazo do contrato administrativo deve ter previsão expressa no edital e disponibilidade
orçamentária. Portanto, a regra geral é de que o contrato tenha vigência dentro do exercício finan-
ceiro, que é de no máximo um ano. Contudo, a Lei 14.133/21 prevê diversas hipóteses, entre os
artigos 106 ao 114, de prazos máximos aos contratos, a depender do objeto:`
